# base plates: the floor (two styles, phone 9:16 and wide 16:9), the window, the counter, the round card
N="Film noir comic book art drawn with heavy brush and ink, like a page inked with a sable brush: bold black brush strokes, large solid black shadows, dry-brush texture on every surface, cross-hatching, ink splatter. Black ink and cool grey wash only, and the light itself drawn in spot colour: warm gold, with one small touch of emerald green and one of signal red. Drawn by hand, not rendered: no photographic light, no 3D render look, no smooth surfaces. No text, no letters, no numbers, no logos, no signs."
L="Flat graphic badge illustration in the style of a bold sports team logo: solid pure black background, flat solid shapes only in cream white, gold yellow, emerald green and signal red, thick hard straight-edged shapes, everything leaning forward like italic lettering, sharp angular speed slashes, no texture, no gradients, no shading, no brush strokes. Not realistic, not 3D, not painted. No text, no letters, no numbers, no logos, no signs."
FL="Establishing panel seen squarely head-on from the visitors' gallery: the trading floor of a grand old New York stock exchange. High on the back wall in the centre a huge round wall clock in a heavy iron frame with a completely blank plain face: no numerals, no hands. Directly under the clock, mounted flat on the wall and facing the viewer squarely, a large wide empty black slate board in a plain dark frame, completely blank and clean, nothing written on it. To the left a big brass bell on an iron bracket. Below, the floor with trading posts, tall arched windows on both sides. Morning: daylight through the windows, a few early traders as small silhouettes."
j(){ python3 -c 'import json,sys;print(json.dumps({"prompt":sys.argv[1],"aspect_ratio":sys.argv[2],"resolution":"1K","quality":"medium","output_format":"png","num_outputs":1}))' "$1" "$2"; }
for s in N L; do eval S=\$$s; k=$(echo $s|tr NL nl)
python3 hd.py fl-$k-am gpt-image-2 "$(j "$FL $S" 9:16)" > log-fl-$k-am.txt 2>&1 &
python3 hd.py fl-$k-am-w gpt-image-2 "$(j "$FL $S" 16:9)" > log-fl-$k-am-w.txt 2>&1 &
python3 hd.py win-$k gpt-image-2 "$(j "Seen squarely head-on: a betting window at an old stock exchange. A dark wooden counter under an ornate iron grille. On the counter in the middle lies one large blank black betting card with a thin gold border, flat, facing up, nothing on it. To its right two rubber stamps standing upright, one with a green handle and one with a red handle. Behind the grille a dark board with four blank black cards with thin gold borders pinned in a row, nothing on them. One lamp above. $S" 3:4)" > log-win-$k.txt 2>&1 &
python3 hd.py ctr-$k gpt-image-2 "$(j "Close-up, seen squarely head-on, wide: the counter of a betting window at night: one large blank black betting card with a thin gold border lying flat in the middle, nothing on it; to the right two rubber stamps standing upright, one with a green handle, one with a red handle; a closed iron grille behind; one lamp's light from above. $S" 16:9)" > log-ctr-$k.txt 2>&1 &
python3 hd.py card-$k gpt-image-2 "$(j "One single blank black betting card with a thin gold border and a perforated tear-off edge at the top, seen squarely head-on, upright, filling the frame, nothing printed on it, lying on a dark surface with a little light. $S" 3:4)" > log-card-$k.txt 2>&1 &
done; wait
